4		"crypto/sha256"
5		"encoding/binary"
6		"encoding/hex"
7		"fmt"
8		"testing"
9	)
10	
11	// 本文件固定轮次提议者选择的回归预期：对固定种子、固定顺序的验证者名单，
12	// 指定轮次必须返回 README 公开规则确定的唯一公钥。
13	// 公开规则：SHA-256(seed || big-endian(round)) 前 8 字节大端整数对名单人数取模。
14	// 表中的预期公钥十六进制按该规则用独立实现（非本包代码）预先算出并固定，
15	// 相同输入产生一致结果或两个入口互相一致都不足以通过本组测试。
16	
17	// fixedValidatorKey 生成确定性的第 i 个验证者公钥（32 字节，内容为 i*32+j+1）。
18	func fixedValidatorKey(i int) []byte {
19		b := make([]byte, 32)
20		for j := range b {
21			b[j] = byte(i*32 + j + 1)
22		}
23		return b
24	}
25	
26	// fixedValidators 返回 count 个确定性验证者公钥，顺序固定。
27	func fixedValidators(count int) [][]byte {
28		vals := make([][]byte, count)
29		for i := range vals {
30			vals[i] = fixedValidatorKey(i)
31		}
32		return vals
33	}
34	
35	// wantProposerByRule 在测试侧按 README 公开规则独立复算指定轮次的提议者，
36	// 不经过被检查的实现，用于交叉核对固定表之外的输入。
37	func wantProposerByRule(seed []byte, validators [][]byte, round uint64) []byte {
38		var buf [8]byte
39		binary.BigEndian.PutUint64(buf[:], round)
40		h := sha256.New()
41		h.Write(seed)
42		h.Write(buf[:])
43		sum := h.Sum(nil)
44		return validators[binary.BigEndian.Uint64(sum[:8])%uint64(len(validators))]
45	}
46	
47	// newProposerTestNode 用给定种子与验证者名单建节点。
48	func newProposerTestNode(t *testing.T, seed []byte, validators [][]byte) *Node {
49		t.Helper()
50		n, err := New(t.TempDir(), Config{Seed: seed, Validators: validators, MaxTxsPerBlock: 4})
51		if err != nil {
52			t.Fatal(err)
53		}
54		return n
55	}
56	
57	// assertProposer 断言 ProposerFor(round) 返回十六进制为 wantHex 的公钥，
58	// 并与测试侧按公开规则独立复算的结果交叉核对。
59	func assertProposer(t *testing.T, n *Node, seed []byte, validators [][]byte, round uint64, wantHex string) {
60		t.Helper()
61		want, err := hex.DecodeString(wantHex)
62		if err != nil {
63			t.Fatalf("bad test fixture hex: %v", err)
64		}
65		got := n.ProposerFor(round)
66		if string(got) != string(want) {
67			t.Fatalf("ProposerFor(%d) = %x, want pinned %s", round, got, wantHex)
68		}
69		if string(got) != string(wantProposerByRule(seed, validators, round)) {
70			t.Fatalf("ProposerFor(%d) = %x, independent rule computation gives %x", round, got, wantProposerByRule(seed, validators, round))
71		}
72	}
73	
74	// 固定种子 + 5 名验证者（非二的幂）+ 固定顺序：逐轮钉住提议者公钥。
75	// 覆盖首轮、255/256 跨字节边界、32 位整数边界与完整 uint64 轮次。
76	func TestProposerForPinnedKeys(t *testing.T) {
77		seed := []byte("proposer-regression-seed-v1")
78		validators := fixedValidators(5)
79		n := newProposerTestNode(t, seed, validators)
80	
81		cases := []struct {
82			round uint64
83			idx   int // 预期公钥在名单中的位置
84			hex   string
85		}{
86			{1, 1, "2122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f40"},
87			{2, 1, "2122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f40"},
88			{3, 2, "4142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f60"},
89			// 255 -> 256 跨越大端编码的字节边界，截断或数值表示变化会在这里选错人。
90			{255, 4, "8182838485868788898a8b8c8d8e8f909192939495969798999a9b9c9d9e9fa0"},
91			{256, 3, "6162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f80"},
92			{257, 2, "4142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f60"},
93			// 32 位无符号整数边界：轮次必须按完整 uint64 参与选择。
94			{4294967295, 1, "2122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f40"},
95			{4294967296, 1, "2122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f40"},
96			{4294967297, 3, "6162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f80"},
97			{9223372036854775808, 4, "8182838485868788898a8b8c8d8e8f909192939495969798999a9b9c9d9e9fa0"},
98			{18446744073709551615, 1, "2122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f40"},
99		}
100		for _, c := range cases {
101			assertProposer(t, n, seed, validators, c.round, c.hex)
102			got := n.ProposerFor(c.round)
103			if string(got) != string(validators[c.idx]) {
104				t.Fatalf("round %d: proposer is validator at pinned index %d", c.round, c.idx)
105			}
106		}
107	}
108	
109	// 种子中的零字节必须按原字节参与选择，不能在第一个零字节处截断。
110	// 若实现只保留零字节前的部分（b"\xAA"），各轮会得到另一组公钥
111	// （如第 1 轮 4142...），本测试固定的预期会立即失败。
112	func TestProposerSeedWithZeroBytes(t *testing.T) {
113		seed := []byte{0xAA, 0x00, 0xBB, 0x00, 0x00, 0xCC}
114		validators := fixedValidators(5)
115		n := newProposerTestNode(t, seed, validators)
116	
117		cases := []struct {
118			round uint64
119			hex   string
120		}{
121			{1, "0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f20"},
122			{2, "0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f20"},
123			{255, "0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f20"},
124			{256, "2122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f40"},
125			{4294967297, "0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f20"},
126		}
127		for _, c := range cases {
128			assertProposer(t, n, seed, validators, c.round, c.hex)
129		}
130		// 佐证测试非空转：按截断种子复算的结果确实不同，截断型回归一定会被发现。
131		truncated := wantProposerByRule([]byte{0xAA}, validators, 1)
132		if string(n.ProposerFor(1)) == string(truncated) {
133			t.Fatal("proposer matches truncated-seed computation; zero bytes were dropped")
134		}
135	}
136	
137	// 名单成员相同但顺序不同：同一索引位置上是不同公钥，
138	// 两种顺序必须各自返回按公开规则落在自己顺序上的成员，不能忽略调用方给的顺序。
139	func TestProposerValidatorOrderMatters(t *testing.T) {
140		seed := []byte("proposer-regression-seed-v1")
141		forward := fixedValidators(5)
142		reversed := [][]byte{fixedValidatorKey(4), fixedValidatorKey(3), fixedValidatorKey(2), fixedValidatorKey(1), fixedValidatorKey(0)}
143	
144		nFwd := newProposerTestNode(t, seed, forward)
145		nRev := newProposerTestNode(t, seed, reversed)
146	
147		// 两种顺序下同一轮次钉住的公钥（按各自顺序套用公开规则）。
148		cases := []struct {
149			round  uint64
150			fwdHex string
151			revHex string
152			fwdIdx int
153			revIdx int
154		}{
155			{1, "2122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f40", "6162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f80", 1, 1},
156			{3, "4142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f60", "4142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f60", 2, 2},
157			{255, "8182838485868788898a8b8c8d8e8f909192939495969798999a9b9c9d9e9fa0", "0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f20", 4, 4},
158			{256, "6162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f80", "2122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f40", 3, 3},
159			{4294967297, "6162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f80", "2122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f40", 3, 3},
160		}
161		for _, c := range cases {
162			assertProposer(t, nFwd, seed, forward, c.round, c.fwdHex)
163			assertProposer(t, nRev, seed, reversed, c.round, c.revHex)
164			if string(nFwd.ProposerFor(c.round)) != string(forward[c.fwdIdx]) {
165				t.Fatalf("round %d: forward order must return member at index %d", c.round, c.fwdIdx)
166			}
167			if string(nRev.ProposerFor(c.round)) != string(reversed[c.revIdx]) {
168				t.Fatalf("round %d: reversed order must return member at index %d", c.round, c.revIdx)
169			}
170		}
171		// 第 1 轮两种顺序落在不同成员上：忽略顺序的实现会在这里露出。
172		if string(nFwd.ProposerFor(1)) == string(nRev.ProposerFor(1)) {
173			t.Fatal("different validator orders must be able to yield different proposers")
174		}
175	}
176	
177	// 单人名单：任何合法轮次都返回唯一成员。
178	func TestProposerSingleValidator(t *testing.T) {
179		only := fixedValidatorKey(0)
180		n := newProposerTestNode(t, []byte("single-validator-seed"), [][]byte{only})
181		for _, round := range []uint64{1, 2, 255, 256, 4294967296, 4294967297, 18446744073709551615} {
182			if got := n.ProposerFor(round); string(got) != string(only) {
183				t.Fatalf("round %d: proposer = %x, want the only validator %x", round, got, only)
184			}
185		}
186		if got := n.CurrentProposer(); string(got) != string(only) {
187			t.Fatalf("CurrentProposer = %x, want the only validator %x", got, only)
188		}
189	}
190	
191	// 两个查询入口遵守同一约定：新节点 CurrentProposer 与 ProposerFor(1)
192	// 都返回第一轮钉住的提议者；EndRound 推进轮次后 CurrentProposer 返回新轮次钉住的提议者。
193	// 该种子下第 1、2 轮提议者是不同成员，轮次不推进的回归无法蒙混。
194	func TestCurrentProposerFollowsRound(t *testing.T) {
195		seed := []byte("round-advance-seed-0")
196		validators := fixedValidators(5)
197		n := newProposerTestNode(t, seed, validators)
198	
199		const round1Hex = "0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f20"
200		const round2Hex = "8182838485868788898a8b8c8d8e8f909192939495969798999a9b9c9d9e9fa0"
201	
202		assertProposer(t, n, seed, validators, 1, round1Hex)
203		if got := fmt.Sprintf("%x", n.CurrentProposer()); got != round1Hex {
204			t.Fatalf("CurrentProposer = %s, want pinned round-1 proposer %s", got, round1Hex)
205		}
206		if string(n.CurrentProposer()) != string(n.ProposerFor(1)) {
207			t.Fatal("CurrentProposer must equal ProposerFor(1) on a new node")
208		}
209	
210		r, err := n.EndRound()
211		if err != nil {
212			t.Fatal(err)
213		}
214		if r != 2 || n.CurrentRound() != 2 {
215			t.Fatalf("round after EndRound = %d (CurrentRound %d), want 2", r, n.CurrentRound())
216		}
217		if got := fmt.Sprintf("%x", n.CurrentProposer()); got != round2Hex {
218			t.Fatalf("CurrentProposer after EndRound = %s, want pinned round-2 proposer %s", got, round2Hex)
219		}
220		assertProposer(t, n, seed, validators, 2, round2Hex)
221	}
222	
223	// 查询其他合法轮次只取得该轮结果：当前轮次与本地提议状态都保持原样。
224	func TestProposerForDoesNotDisturbState(t *testing.T) {
225		seed := []byte("proposer-regression-seed-v1")
226		validators := fixedValidators(5)
227		n := newProposerTestNode(t, seed, validators)
228	
229		// 尚未产生本地提议时查询其他轮次。
230		assertProposer(t, n, seed, validators, 7, "4142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f60")
231		if n.CurrentRound() != 1 {
232			t.Fatalf("CurrentRound = %d after querying round 7, want 1", n.CurrentRound())
233		}
234		if _, ok := n.Proposal(); ok {
235			t.Fatal("querying another round must not create a local proposal")
236		}
237	
238		// 已有本地提议后查询过去与未来的轮次，提议与轮次都不变。
239		p, err := n.Propose()
240		if err != nil {
241			t.Fatal(err)
242		}
243		assertProposer(t, n, seed, validators, 3, "4142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f60")
244		assertProposer(t, n, seed, validators, 4294967297, "6162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f80")
245		if n.CurrentRound() != 1 {
246			t.Fatalf("CurrentRound = %d, want 1", n.CurrentRound())
247		}
248		p2, ok := n.Proposal()
249		if !ok || p2.BlockID != p.BlockID {
250			t.Fatalf("local proposal changed after querying other rounds: %+v", p2)
251		}
252	}
253	
254	// 返回的公钥是调用方手中的副本：改写它不影响后续查询结果。
255	func TestProposerReturnedKeyIsCopy(t *testing.T) {
256		seed := []byte("proposer-regression-seed-v1")
257		validators := fixedValidators(5)
258		n := newProposerTestNode(t, seed, validators)
259	
260		const round1Hex = "2122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f40"
261		got := n.ProposerFor(1)
262		if fmt.Sprintf("%x", got) != round1Hex {
263			t.Fatalf("ProposerFor(1) = %x, want %s", got, round1Hex)
264		}
265		// 改写返回副本的每一个字节。
266		for i := range got {
267			got[i] ^= 0xff
268		}
269		cur := n.CurrentProposer()
270		cur[0] ^= 0xff
271	
272		assertProposer(t, n, seed, validators, 1, round1Hex)
273		if fmt.Sprintf("%x", n.CurrentProposer()) != round1Hex {
274			t.Fatal("mutating a returned proposer key corrupted later queries")
275		}
276		// 名单本身也不受影响：其他轮次仍按原名单选择。
277		assertProposer(t, n, seed, validators, 256, "6162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f80")
278	}
